GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Place high-pressure models first, then improve the minimax KVPR by moves/swaps."""
    placement = {i: [] for i in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num

    def score():
        return max(load[i] / free[i] if free[i] > 0 else float("inf")
                   for i in range(gpu_num))

    # Choose the destination producing the smallest global maximum after placement,
    # rather than the GPU with the smallest pressure before placement.
    for m in sorted(models, key=lambda x: (-(x.req_rate / x.slo), -x.model_size)):
        s, w = m.model_size, m.req_rate / m.slo
        best, value = None, float("inf")
        for g in range(gpu_num):
            if s <= free[g]:
                free[g] -= s
                load[g] += w
                v = score()
                free[g] += s
                load[g] -= w
                if v < value:
                    best, value = g, v
        if best is None:
            raise ValueError("Models do not fit in the available GPU memory")
        placement[best].append(m)
        free[best] -= s
        load[best] += w

    # Best-improvement neighborhood search repairs packing and load-balance errors.
    for _ in range(min(5, len(models))):
        best, value = None, score()
        for a in range(gpu_num):
            for m in placement[a]:
                s, w = m.model_size, m.req_rate / m.slo
                for b in range(gpu_num):
                    if a == b or s > free[b]:
                        continue
                    free[a] += s; load[a] -= w
                    free[b] -= s; load[b] += w
                    v = score()
                    free[a] -= s; load[a] += w
                    free[b] += s; load[b] -= w
                    if v < value:
                        best, value = ("move", a, b, m), v

        for a in range(gpu_num):
            for b in range(a + 1, gpu_num):
                for x in placement[a]:
                    for y in placement[b]:
                        xs, xw = x.model_size, x.req_rate / x.slo
                        ys, yw = y.model_size, y.req_rate / y.slo
                        if ys > free[a] + xs or xs > free[b] + ys:
                            continue
                        free[a] += xs - ys; load[a] += yw - xw
                        free[b] += ys - xs; load[b] += xw - yw
                        v = score()
                        free[a] -= xs - ys; load[a] -= yw - xw
                        free[b] -= ys - xs; load[b] -= xw - yw
                        if v < value:
                            best, value = ("swap", a, b, x, y), v

        if best is None:
            break
        if best[0] == "move":
            _, a, b, m = best
            placement[a].remove(m); placement[b].append(m)
            free[a] += m.model_size; load[a] -= m.req_rate / m.slo
            free[b] -= m.model_size; load[b] += m.req_rate / m.slo
        else:
            _, a, b, x, y = best
            placement[a].remove(x); placement[b].remove(y)
            placement[a].append(y); placement[b].append(x)
            free[a] += x.model_size - y.model_size
            load[a] += y.req_rate / y.slo - x.req_rate / x.slo
            free[b] += y.model_size - x.model_size
            load[b] += x.req_rate / x.slo - y.req_rate / y.slo

    return placement

